// _key_putMapStringMapFloat64Bool writes the encoding of x, a
// map[string]map[float64]bool, into the end of buf, which has room for it, and
// returns its length. It fails for a value that fails to encode, which loc and
// num locate.
func _key_putMapStringMapFloat64Bool(buf []byte, x map[string]map[float64]bool, loc string, num int) (int, error) {
	i := len(buf)
	if len(x) <= 16 {
		type pair = wire.Pair[string, map[float64]bool]
		var arr [16]pair
		pairs := arr[:0]
		for mk, mv := range x {
			pairs = append(pairs, pair{Key: mk, Value: mv})
		}
		wire.SortPairs(pairs)
		for k := len(pairs) - 1; k >= 0; k-- {
			{
				w, err := _key_putMapFloat64Bool(buf[:i], pairs[k].Value, loc, num)
				if err != nil {
					return 0, err
				}
				i -= w
			}
			i = wire.PutRaw(buf, i, pairs[k].Key)
			i = wire.PutUvarint(buf, i, uint64(len(pairs[k].Key)))
		}
	} else {
		keys := make([]string, 0, len(x))
		for mk := range x {
			keys = append(keys, mk)
		}
		slices.Sort(keys)
		for k := len(keys) - 1; k >= 0; k-- {
			mk := keys[k]
			mv := x[mk]
			{
				w, err := _key_putMapFloat64Bool(buf[:i], mv, loc, num)
				if err != nil {
					return 0, err
				}
				i -= w
			}
			i = wire.PutRaw(buf, i, mk)
			i = wire.PutUvarint(buf, i, uint64(len(mk)))
		}
	}
	i = wire.PutUvarint(buf, i, uint64(len(buf)-i))
	return len(buf) - i, nil
}

// _key_putMapArray4ByteString writes the encoding of x, a map[[4]byte]string,
// into the end of buf, which has room for it, and returns its length.
func _key_putMapArray4ByteString(buf []byte, x map[[4]byte]string) int {
	i := len(buf)
	var arr [16][4]byte
	keys := arr[:0]
	for mk := range x {
		keys = append(keys, mk)
	}
	slices.SortFunc(keys, func(a, b [4]byte) int {
		return bytes.Compare(a[:], b[:])
	})
	for k := len(keys) - 1; k >= 0; k-- {
		mk := keys[k]
		mv := x[mk]
		i = wire.PutRaw(buf, i, mv)
		i = wire.PutUvarint(buf, i, uint64(len(mv)))
		i = wire.PutRaw(buf, i, mk[:])
		i = wire.PutUvarint(buf, i, uint64(len(mk)))
	}
	i = wire.PutUvarint(buf, i, uint64(len(buf)-i))
	return len(buf) - i
}

