// _key_readPtrFloat64 decodes the *float64 at the start of data into *dst and
// returns the length of its encoding: nil for the presence byte 0, and for the
// presence byte 1 the value that follows, into the value that *dst points at or
// into a new one. data starts at offset off of slab, and the decode enters
// depth levels below the value at most. loc and num locate the field in errors.
func _key_readPtrFloat64(dst **float64, data []byte, slab string, off, depth int, loc string, num int) (int, error) {
	if depth < 0 {
		return 0, wire.DepthError(loc, num, off)
	}
	present, err := wire.Presence(data, loc, num, off)
	if err != nil {
		return 0, err
	}
	if !present {
		*dst = nil
		return 1, nil
	}
	x := *dst
	if x == nil {
		x = new(float64)
		*dst = x
	}
	i := 1
	u, n := wire.Uint64(data[i:])
	if n <= 0 {
		return 0, wire.ReadError(n, loc, num, off+i)
	}
	*x = math.Float64frombits(u)
	i += n
	return i, nil
}

// _key_negzeroPtrFloat64 reports whether x, a map key of type *float64, has a
// float component of -0.0, which the projection of the key writes as +0.0.
func _key_negzeroPtrFloat64(x *float64) bool {
	return x != nil && *x == 0 && math.Signbit(*x)
}

// _key_readCoord sets the Coord that m points at to the value encoded in data
// and reuses its memory, as DecodeKanon does. data starts at offset off of
// slab, and the decode enters depth levels below the value at most.
func _key_readCoord(m *Coord, data []byte, slab string, off, depth int) error {
	m.Lat = 0
	m.Lon = 0
	return _key_mergeCoord(m, data, slab, off, depth)
}

// _key_negzeroCoord reports whether x, a map key of type Coord, has a float
// component of -0.0, which the projection of the key writes as +0.0.
func _key_negzeroCoord(x Coord) bool {
	return x.Lat == 0 && math.Signbit(x.Lat) || x.Lon == 0 && math.Signbit(float64(x.Lon))
}

// _key_canonAny reports whether x, a map key of type any, is the key that a
// decode of its projection yields, so that the map of a decode needs no other
// check to keep one entry for the keys of one projection.
func _key_canonAny(x any) bool {
	switch x.(type) {
	case nil:
		return true
	case float64:
		return true
	case string:
		return true
	}
	return false
}

// _key_readAny decodes the any at the start of data into *dst and returns the
// length of its encoding: the number of its concrete type and the value of that
// type, into the value that *dst stores when it has that type. It fails for a
// type number that the list does not name. data starts at offset off of slab,
// and the decode enters depth levels below the value at most. loc and num
// locate the field in errors.
func _key_readAny(dst *any, data []byte, slab string, off, depth int, loc string, num int) (int, error) {
	if depth < 0 {
		return 0, wire.DepthError(loc, num, off)
	}
	t, i := wire.Uvarint(data)
	if i <= 0 {
		return 0, wire.ReadError(i, loc, num, off)
	}
	if i > 1 && data[i-1] == 0 {
		return 0, wire.LongFormError(i, loc, num, off)
	}
	switch t {
	case 0:
		*dst = nil
	case 1:
		var x float64
		u, n := wire.Uint64(data[i:])
		if n <= 0 {
			return 0, wire.ReadError(n, loc, num, off+i)
		}
		x = math.Float64frombits(u)
		i += n
		*dst = x
	case 2:
		var x string
		l, n := wire.Uvarint(data[i:])
		if n <= 0 || uint64(len(data)-i-n) < l {
			return 0, wire.ReadError(n, loc, num, off+i)
		}
		if n > 1 && data[i+n-1] == 0 {
			return 0, wire.LongFormError(n, loc, num, off+i)
		}
		i += n
		x = slab[off+i : off+i+int(l)]
		i += int(l)
		*dst = x
	default:
		return 0, wire.TypeError(t, loc, num, off)
	}
	return i, nil
}

// _key_negzeroAny reports whether x, a map key of type any, has a float
// component of -0.0, which the projection of the key writes as +0.0.
func _key_negzeroAny(x any) bool {
	switch x := x.(type) {
	case float64:
		return x == 0 && math.Signbit(x)
	}
	return false
}

